// Edite aqui. É o único lugar com endereço da ponte, token e tamanho das imagens.
return [{ json: {
  // A ponte roda no computador, como o usuário cadu (scripts/ponte.py). De dentro do container
  // runv2-n8n-1 o computador é o gateway da rede runv2_default: 172.19.0.1.
  // (host.docker.internal NÃO existe nesse container; ele não tem extra_hosts.)
  url_ponte: 'http://172.19.0.1:7777',
  token_ponte: 'COLE_AQUI_O_TOKEN_QUE_A_PONTE_MOSTRA',
  // Conjunto de cards. Os nomes dos modelos em "Montar entrada dos cards" são os do dict-v1.
  serie: 'dict-v1',
  // Pasta de saída das imagens: iaclube_n8n/<tipo>/ (separa o Dicionário das Notícias, que usam 'noticias').
  tipo: 'dicionario',
  marca: '@iaclube',
  // Acrescentado ao fim de todo prompt de imagem: é o que deixa as imagens com a mesma cara.
  // As cores são as do card do Dicionário (fundo #f2f2f1, texto #0e1626, acento #e63415).
  estilo_comum: 'flat vector editorial illustration, bold simple shapes, soft gradients, vivid red-orange and deep navy palette on a warm off-white background, clean composition, wide landscape framing, no text, no letters, no numbers, no logos, no watermark',
  // Tamanho das imagens (múltiplos de 16). Pequena 3:2 = 624 x 416 (cerca de 4 min cada).
  // Média 3:2 = 944 x 624 (cerca de 9 min cada). O espaço da imagem no card é 839 x 592.
  largura: 624,
  altura: 416,
  espera_subir_s: 5,            // pausa depois de subir cada servidor
  intervalo_consulta_s: 30,     // de quanto em quanto tempo olhar a fila de imagens
  tempo_maximo_geracao_min: 90  // desiste se as imagens passarem disso (são só 2)
} }];

// Traz todos os termos ja usados; se a tabela estiver vazia, retorna lista vazia (sem quebrar).
const linhas = $input.all().map(item => item.json);

const usados = linhas
  .map(l => l.termo)
  .filter(t => t);

const usadosNormalizados = linhas
  .map(l => l.termo_normalizado || l.termo)
  .filter(t => t);

return [{
  json: {
    termos_usados: usados.join(', ') || 'nenhum ainda',
    termos_normalizados: usadosNormalizados
  }
}];

try {
  const raw = $input.first().json.output;

  // A IA as vezes envolve o JSON em blocos de codigo markdown (```json ... ```).
  const clean = String(raw).replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);

  // ---------- 1) CONTRATO MINIMO ----------
  const faltando = [];
  if (!parsed.termo) faltando.push('termo');
  if (!parsed.tema_card) faltando.push('tema_card');
  if (!parsed.definicao_curta) faltando.push('definicao_curta');
  if (!Array.isArray(parsed.slides) || parsed.slides.length === 0) faltando.push('slides');
  if (!parsed.legendas) faltando.push('legendas');
  else {
    for (const rede of ['instagram', 'facebook', 'linkedin']) {
      if (!parsed.legendas[rede]) faltando.push('legendas.' + rede);
    }
  }
  if (faltando.length) {
    return [{ json: { erro: true, mensagem: 'Campos ausentes: ' + faltando.join(', '), bruto: clean } }];
  }

  const avisos = [];

  // ---------- 2) NORMALIZACAO DE PAPEIS ----------
  // A estrutura narrativa e o ponto do post, entao ela e reparada aqui em vez de
  // derrubar o roteiro inteiro. So bloqueia o que nao da para reconstruir.
  let slides = parsed.slides
    .filter(s => s && (s.titulo || s.texto))
    .map(s => ({
      papel: String(s.papel || '').trim().toLowerCase(),
      titulo_leve: String(s.titulo_leve || '').trim(),
      titulo: String(s.titulo || '').trim(),
      texto: String(s.texto || '').trim(),
      prompt_imagem: String(s.prompt_imagem || '').replace(/\s+/g, ' ').trim()
    }));

  // A IA foi instruida a nao escrever CTA. Se escrever, o slide sai aqui --
  // o CTA real e adicionado depois, por codigo, sempre igual.
  // A heuristica de texto so olha o ULTIMO slide, e com padroes especificos:
  // 'siga' solto poderia derrubar um slide legitimo ('siga esse raciocinio').
  const ehFechamento = (s) => /sig(a|ue) (a p[aá]gina|o @|a gente)|nos sig(a|ue)|obrigad[oa] por|at[eé] a pr[oó]xima|salve esse post|compartilhe esse post|link (na|da) bio/i.test(s.titulo + ' ' + s.texto);
  const ultimo = slides[slides.length - 1];
  const cta_indevido = slides.filter(s => s.papel === 'cta' || (s === ultimo && ehFechamento(s)));
  if (cta_indevido.length) {
    slides = slides.filter(s => !cta_indevido.includes(s));
    avisos.push('a IA escreveu ' + cta_indevido.length + ' slide(s) de fechamento; foram removidos');
  }

  // Papel ausente (formato antigo) ou fora de ordem: reconstroi por posicao.
  const semPapel = slides.filter(s => !['gancho', 'contexto', 'desenvolvimento'].includes(s.papel));
  if (semPapel.length) {
    avisos.push('papel ausente ou invalido em ' + semPapel.length + ' slide(s); atribuido por posicao');
  }
  const gancho = slides.find(s => s.papel === 'gancho') || slides[0];
  const contexto = slides.find(s => s.papel === 'contexto' && s !== gancho) ||
                   slides.find(s => s !== gancho);
  const desenvolvimento = slides.filter(s => s !== gancho && s !== contexto);

  if (!gancho || !contexto || desenvolvimento.length === 0) {
    return [{ json: { erro: true, mensagem: 'Estrutura insuficiente: precisa de gancho + contexto + ao menos 1 desenvolvimento. Vieram ' + slides.length + ' slides.', bruto: clean } }];
  }

  const ordemOriginal = slides.map(s => s.papel).join(',');
  gancho.papel = 'gancho';
  contexto.papel = 'contexto';
  desenvolvimento.forEach(s => { s.papel = 'desenvolvimento'; });
  slides = [gancho, contexto, ...desenvolvimento];
  if (ordemOriginal !== slides.map(s => s.papel).join(',') && !semPapel.length) {
    avisos.push('slides estavam fora da ordem gancho > contexto > desenvolvimento; reordenados');
  }

  // ---------- 3) AVISOS DE FORMA (nao bloqueiam) ----------
  // A arte tem 4 cards de desenvolvimento (dict-v1). Com menos, ficam cards de fora; com mais, sobram slides.
  if (desenvolvimento.length !== 4) avisos.push(desenvolvimento.length + ' slides de desenvolvimento (esperado 4, um para cada card da arte)');

  // Limites dos cards do conjunto dict-v1 (iaclube_n8n/templates/dict-v1/limites.json):
  // gancho -> capa, contexto -> definicao, desenvolvimento 1 a 4 -> texto-com-imagem-1,
  // texto-com-imagem-2, texto, texto-com-inicio-fino. O titulo conta titulo_leve + titulo juntos.
  const DEV = [
    { titulo: 23, max: 175 }, { titulo: 32, max: 163 }, { titulo: 26, max: 169 }, { titulo: 29, max: 152 }
  ];
  const limites = {
    gancho: { titulo: 22, min: 0, max: 87 },
    contexto: { titulo: 18, min: 80, max: 152 }
  };
  let posDev = 0;
  slides.forEach((s, i) => {
    let lim = limites[s.papel];
    if (s.papel === 'desenvolvimento') {
      const d = DEV[Math.min(posDev, DEV.length - 1)];
      lim = { titulo: d.titulo, min: 90, max: d.max };
      if (posDev < 2) {
        if (!s.prompt_imagem) avisos.push('slide ' + (i + 1) + ' (desenvolvimento ' + (posDev + 1) + ') sem prompt_imagem -- a imagem vai sair de um prompt generico');
        else if (s.prompt_imagem.length > 300) avisos.push('prompt_imagem do slide ' + (i + 1) + ' com ' + s.prompt_imagem.length + ' chars, limite 300');
      }
      posDev++;
    }
    const n = s.texto.length;
    if (n > lim.max) avisos.push('slide ' + (i + 1) + ' (' + s.papel + ') com ' + n + ' chars, limite ' + lim.max);
    if (lim.min && n < lim.min) avisos.push('slide ' + (i + 1) + ' (' + s.papel + ') com ' + n + ' chars, minimo ' + lim.min);
    const t = [s.titulo_leve, s.titulo].filter(Boolean).join(' ').length;
    if (t > lim.titulo) avisos.push('titulo do slide ' + (i + 1) + ' (' + s.papel + ') com ' + t + ' chars, limite ' + lim.titulo);
  });

  // Gancho que abre como aula em vez de abrir tensao.
  if (/^(voce sabe|você sabe|hoje (vamos|eu vou)|o que e|o que é)\b/i.test(gancho.titulo + ' ' + gancho.texto)) {
    avisos.push('o gancho comeca com formula de aula ("voce sabe o que e...") -- reescrever antes de aprovar');
  }

  return [{ json: { ...parsed, slides, erro: false, avisos } }];
} catch (e) {
  return [{ json: { erro: true, mensagem: e.message } }];
}

// Normaliza o texto antes de gravar na memoria: minusculo, sem acento, sem pontuacao.
function normalizar(texto) {
  return String(texto || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ");
}

const dados = $input.first().json;

return [{
  json: {
    ...dados,
    termo_normalizado: normalizar(dados.termo),
    data: new Date().toISOString(),
    status: "gerado"
  }
}];

// SLIDE DE CTA -- FONTE UNICA DE VERDADE
// O ultimo slide do carrossel e sempre este, e nao e escrito pela IA. Motivo:
// e a unica parte da peca que nao deve variar de semana para semana. Se voce
// quiser mudar a chamada da pagina, mude AQUI e vale para todo Dicionario IA.
// (Se quiser mudar tambem em quarta e sexta, replique este node la.)

const PERFIL = '@iaclube';
const SITE = 'iaclube.help';

const d = $input.first().json;
const termo = String(d.termo || '').trim();

// Interpolar o termo da variacao sem risco de estourar o limite de arte:
// termo curto entra na frase, termo longo cai na versao generica.
const texto = termo.length > 0 && termo.length <= 28
  ? `Se ${termo} fez sentido agora, tem termo novo toda semana no ${PERFIL}. O resto do conteúdo está em ${SITE}.`
  : `Tem termo novo toda semana no ${PERFIL}. O resto do conteúdo está em ${SITE}.`;

const slideCta = {
  papel: 'cta',
  titulo: 'Ficou mais claro?',
  texto
};

return [{
  json: {
    ...d,
    slides: [...(d.slides || []), slideCta]
  }
}];

// CONTRATO COM O FLUXO DE DESIGN
// A descricao do card pai e a fonte unica de verdade. O fluxo de design vai ler
// esta descricao e cortar pelos marcadores '## ' abaixo. Se voce editar o texto
// no Trello durante a revisao, edite DENTRO das secoes -- nao apague nem renomeie
// os cabecalhos, senao o parser do design nao encontra nada.
//
// Cada slide vem marcado com o papel narrativo (GANCHO / CONTEXTO /
// DESENVOLVIMENTO / CTA). O papel nao e decoracao: o template de arte usa ele
// para escolher o layout (capa, corpo, fechamento). Nao remova o slide CTA e
// nao mude a ordem dos papeis na revisao.

const d = $input.first().json;

const slides = (d.slides || [])
  .map((s, i) => `### ${i + 1} | ${String(s.papel || '').toUpperCase()} | ${[s.titulo_leve, s.titulo].filter(Boolean).join(' ')}\n${s.texto}`)
  .join('\n\n');

// Os prompts de imagem ficam no card para conferencia: e deles que a arte sai.
const prompts = (d.slides || [])
  .filter(s => s.papel === 'desenvolvimento')
  .slice(0, 2)
  .map((s, i) => `${i + 1}. ${s.prompt_imagem || '(sem prompt: a automacao usa um generico)'}`)
  .join('\n');

const partes = [
  d.definicao_curta,
  '',
  '## SLIDES',
  slides,
  '',
  '## LEGENDA INSTAGRAM',
  d.legendas.instagram,
  '',
  '## LEGENDA FACEBOOK',
  d.legendas.facebook,
  '',
  '## LEGENDA LINKEDIN',
  d.legendas.linkedin,
  '',
  '## HASHTAGS',
  (d.hashtags || []).join(' '),
  '',
  '## PROMPTS DE IMAGEM',
  prompts
];

if (d.avisos && d.avisos.length) {
  partes.push('', '## AVISOS DA AUTOMACAO', d.avisos.map(a => '- ' + a).join('\n'));
}

return [{
  json: {
    ...d,
    descricao: partes.join('\n')
  }
}];

// Depois do node de checklist, $json e o objeto da checklist -- entao $json.id
// e o checklistId. Um item so entra e um item so sai: sem risco de pareamento.
const checklistId = $input.first().json.id;

const tarefas = [
  'Ler so o slide 1: ele faria voce parar de rolar?',
  'Conferir se cada slide abre algo que o proximo responde',
  'Revisar as tres legendas',
  'Aprovar texto (mover card para Aprovado)',
  'Conferir os cards gerados (a pasta vem num comentario deste card)',
  'Aprovar arte',
  'Publicar nas tres redes'
];

return [{ json: { checklistId, tarefas } }];

// PONTE ENTRE O TEXTO E A ARTE
// Transforma o Dicionario que acabou de ir para o Trello no mesmo formato do arquivo
// entradas/exemplo-noticias-10.json, que o resto do fluxo (igual ao noticias-2-arte) espera:
//   { nome, estilo_comum, entrada: { serie, data, assunto, marca, cards }, imagens }
// Os textos vem dos slides de 'Adiciona slide de CTA': o que esta no card do Trello e o que
// vai para a arte. Cada slide vira um card do dict-v1, sempre nesta ordem:
//   gancho -> capa | contexto -> definicao | desenvolvimento 1..4 -> texto-com-imagem-1,
//   texto-com-imagem-2, texto, texto-com-inicio-fino | cta -> encerramento
// Os marcadores de peso ({leve|...}, {normal|...}, **...**) reproduzem os titulos dos cards originais.
const cfg = $('Configuração').first().json;
const d = $('Adiciona slide de CTA').first().json;
const slides = Array.isArray(d.slides) ? d.slides : [];
const doPapel = (papel) => slides.filter(s => s.papel === papel);
const umaLinha = (t) => String(t || '').replace(/\s+/g, ' ').trim();
const termo = umaLinha(d.termo);

// nome de arquivo seguro para o gerador: minusculas, sem acento, so letras, numeros e '-'
const slug = (t) => String(t || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  .slice(0, 40).replace(/-+$/g, '');
const negrito = (texto, trecho) => (trecho ? String(texto).split(trecho).join('**' + trecho + '**') : texto);

const gancho = doPapel('gancho')[0] || { titulo_leve: '', titulo: termo, texto: '' };
const contexto = doPapel('contexto')[0] || { titulo: termo, texto: '' };
const cta = doPapel('cta')[0] || { titulo: '', texto: '' };
const avisos_ponte = [];

// Quantos slides de desenvolvimento: 4 e o normal (um por card). Com menos, usa os modelos
// da tabela (os dois com imagem primeiro); com mais, os que sobram ficam de fora.
const MODELOS = {
  2: ['texto-com-imagem-1', 'texto'],
  3: ['texto-com-imagem-1', 'texto-com-imagem-2', 'texto'],
  4: ['texto-com-imagem-1', 'texto-com-imagem-2', 'texto', 'texto-com-inicio-fino'],
};
let desenvolvimento = doPapel('desenvolvimento');
if (desenvolvimento.length > 4) {
  avisos_ponte.push(desenvolvimento.length + ' slides de desenvolvimento: só os 4 primeiros viraram card');
  desenvolvimento = desenvolvimento.slice(0, 4);
}
const modelos = MODELOS[desenvolvimento.length] || MODELOS[2].slice(0, desenvolvimento.length);
if (desenvolvimento.length < 4) avisos_ponte.push('só ' + desenvolvimento.length + ' slides de desenvolvimento: o carrossel saiu com menos cards que o normal (7)');

const cards = [];
const imagens = [];

// capa: começo fino, quebra de linha, resto em destaque ('{leve|A IA pode te}\nesquecer.')
cards.push({ modelo: 'capa', campos: {
  titulo: gancho.titulo_leve ? '{leve|' + umaLinha(gancho.titulo_leve) + '}\n' + umaLinha(gancho.titulo) : umaLinha(gancho.titulo),
  corpo: umaLinha(gancho.texto),
} });

// definicao: 'Isso é' + o termo + a explicação
cards.push({ modelo: 'definicao', campos: {
  antetitulo: 'Isso é',
  titulo: umaLinha(contexto.titulo) || termo,
  corpo: umaLinha(contexto.texto),
} });

desenvolvimento.forEach((s, i) => {
  const modelo = modelos[i];
  const leve = umaLinha(s.titulo_leve);
  const resto = umaLinha(s.titulo);
  let titulo;
  if (modelo === 'texto-com-inicio-fino') titulo = leve ? '{normal|' + leve + '} ' + resto : resto;
  else if (modelo === 'texto') titulo = [leve, resto].filter(Boolean).join(' ');
  else titulo = leve ? leve + ' **' + resto + '**' : '**' + resto + '**';   // texto-com-imagem-1 e -2
  cards.push({ modelo, campos: { titulo, corpo: umaLinha(s.texto) } });

  if (modelo.startsWith('texto-com-imagem')) {
    imagens.push({
      card: cards.length,            // posicao do card que acabou de entrar (o primeiro e 1)
      mascara: 'imagem_1',
      nome_arquivo: 'dicionario-' + (slug(termo) || 'termo') + '-' + (imagens.length + 1),
      prompt: umaLinha(s.prompt_imagem) ||
        'a simple friendly editorial illustration that explains the artificial intelligence concept: ' + termo,
    });
  }
});

// encerramento: o CTA fixo do nó 'Adiciona slide de CTA', com o termo e o perfil em negrito
cards.push({ modelo: 'encerramento', campos: {
  titulo: umaLinha(cta.titulo).replace(/^(\S+ \S+) (\S+)$/, '$1\n$2'),
  corpo: negrito(negrito(umaLinha(cta.texto), termo), '@iaclube'),
} });

const data = $now.toISODate();
return [{ json: {
  versao: 1,
  tipo: cfg.tipo || 'dicionario',
  nome: ('Dicionário IA ' + data + ' ' + termo).trim().slice(0, 80),
  estilo_comum: cfg.estilo_comum || '',
  entrada: { serie: cfg.serie, data, assunto: termo, marca: cfg.marca, cards },
  imagens,
  avisos_ponte,
} }];

const cfg = $('Configuração').first().json;
const dados = $input.first().json;

const erros = [];
const cards = dados.entrada && dados.entrada.cards;
if (!Array.isArray(cards) || cards.length === 0) erros.push('entrada.cards precisa ser uma lista com pelo menos um card');
if (!Array.isArray(dados.imagens) || dados.imagens.length === 0) erros.push('imagens precisa ser uma lista com pelo menos uma imagem');
if (dados.imagens && dados.imagens.length > 20) erros.push('no máximo 20 imagens por execução (limite da consulta de fila)');
if (cfg.largura % 16 || cfg.altura % 16) erros.push('largura e altura da Configuração precisam ser múltiplos de 16');

const usados = new Set();
(dados.imagens || []).forEach((im, i) => {
  const onde = 'imagens[' + i + ']';
  if (!Number.isInteger(im.card) || !cards || im.card < 1 || im.card > cards.length) {
    erros.push(onde + '.card deve ser a posição de um card (1 a ' + (cards ? cards.length : '?') + ')');
  } else if (usados.has(im.card + '/' + im.mascara)) {
    erros.push(onde + ': o card ' + im.card + ' já tem imagem para a máscara ' + im.mascara);
  } else {
    usados.add(im.card + '/' + im.mascara);
  }
  if (typeof im.mascara !== 'string' || !im.mascara) erros.push(onde + '.mascara é obrigatória (por exemplo imagem_1)');
  if (typeof im.prompt !== 'string' || im.prompt.trim().length < 3) erros.push(onde + '.prompt é obrigatório');
});
if (erros.length) throw new Error('Entrada inválida:\n- ' + erros.join('\n- '));

return [{ json: {
  cfg,
  nome: dados.nome || 'carrossel_noticias',
  tipo: dados.tipo || 'noticias',   // vira a pasta iaclube_n8n/<tipo>/ nas Imagens
  estilo_comum: (dados.estilo_comum || '').trim(),
  entrada: dados.entrada,
  imagens: dados.imagens,
} }];

const v = $('Validar entrada').first().json;
const { largura, altura } = v.cfg;
return v.imagens.map((im, i) => {
  const nome = im.nome_arquivo || 'noticia-' + String(i + 1).padStart(2, '0');
  const prompt = v.estilo_comum ? im.prompt.trim() + ', ' + v.estilo_comum : im.prompt.trim();
  return { json: {
    indice: i,
    card: im.card,
    mascara: im.mascara,
    nome_arquivo: nome,
    corpo: { prompt, width: largura, height: altura, nome_arquivo: nome },
  } };
});

const pedidos = $('Montar pedidos de imagem').all();
const respostas = $input.all();
const tickets = respostas.map((r, i) => ({
  ticket: r.json.ticket,
  card: pedidos[i].json.card,
  mascara: pedidos[i].json.mascara,
  nome_arquivo: pedidos[i].json.nome_arquivo,
}));
return [{ json: { tickets, total: tickets.length, iniciado_em: Date.now() } }];

const r = $('Reunir tickets').first().json;
const cfg = $('Validar entrada').first().json.cfg;
const jobs = $input.first().json.jobs || {};
const cont = { queued: 0, running: 0, completed: 0, failed: 0, outro: 0 };
const falhas = [];
for (const t of r.tickets) {
  const j = jobs[t.ticket] || { status: 'not_found' };
  if (j.status in cont) cont[j.status]++; else cont.outro++;
  if (j.status === 'failed' || j.status === 'not_found') {
    falhas.push('card ' + t.card + ' (' + t.nome_arquivo + '): ' + (j.error || j.status));
  }
}
const minutos = Math.round((Date.now() - r.iniciado_em) / 6000) / 10;
let estado = 'esperando';
let motivo = '';
if (falhas.length) {
  estado = 'falhou';
  motivo = 'Falha ao gerar imagem: ' + falhas.join(' | ');
} else if (cont.completed === r.total) {
  estado = 'concluido';
} else if (minutos > cfg.tempo_maximo_geracao_min) {
  estado = 'tempo_esgotado';
  motivo = 'As imagens passaram de ' + cfg.tempo_maximo_geracao_min + ' min e ainda faltam ' + (r.total - cont.completed) + '.';
}
return [{ json: { estado, motivo, minutos, total: r.total, ...cont } }];

const v = $('Validar entrada').first().json;
const tickets = $('Listar tickets').all();
const resultados = $input.all();
const imagens = [];
const problemas = [];
resultados.forEach((r, i) => {
  const t = tickets[i].json;
  const caminho = r.json.output_path;
  if (!r.json.ready || !caminho) {
    problemas.push('card ' + t.card + ' (' + t.nome_arquivo + '): imagem sem caminho de arquivo');
  } else {
    imagens.push({ card: t.card, mascara: t.mascara, caminho });
  }
});
if (problemas.length) return [{ json: { ok: false, motivo: problemas.join(' | ') } }];
return [{ json: { ok: true, pedido: {
  versao: 1,
  nome: v.nome,
  tipo: v.tipo,
  entrada: v.entrada,
  imagens,
  // instrucoes: true grava, ao lado dos PNG, o <base>_instrucoes.json: o arquivo que a tela do
  // gerenciador reabre ("Abrir a partir de instruções") para corrigir qualquer detalhe de formatação.
  exportacao: { formatos: ['png'], escalas: [1], instrucoes: true },
} } }];

const r = $input.first().json;
const arquivos = (r.arquivos || []);
return [{ json: {
  ok: r.ok === true,
  pasta: r.pasta,
  instrucoes: r.instrucoes || null,   // caminho do .json de instruções (ao lado dos PNG)
  geracao_id: r.geracao_id,
  quantidade: arquivos.length,
  arquivos: arquivos.map(a => a.caminho),
  avisos: (r.avisos || []).map(a => (a.rotulo ? a.rotulo + ': ' : '') + a.mensagem),
} }];

// Devolve o resultado da produção (os nós anteriores só desligaram o servidor e comentaram no Trello).
const t = $('Trello - Criar card').first().json;
return [{ json: { ...$('Montar resultado').first().json, trello: t.shortUrl || t.url || t.id } }];

const j = $input.first().json;
let msg;
if (j.motivo) {
  msg = j.motivo;
} else if (j.ready === false) {
  msg = 'O gerador subiu, mas não está pronto: ' + (j.problems || []).join(' | ');
} else if (j.error) {
  const e = j.error;
  msg = (e.message || JSON.stringify(e)) + (e.description ? ' — ' + e.description : '');
} else if (j.stdout) {
  msg = j.stdout;
} else {
  msg = 'Falha sem detalhe: ' + JSON.stringify(j).slice(0, 500);
}
return [{ json: { mensagem: msg } }];

